Item.method_code:
if (Environment.GetEnvironmentVariable("INNOVATOR_HARNESS_REFERENCE_CAPTURE") == "1")
{
    var aml = Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes(this.ToString()));
    Console.WriteLine("HARNESS_REFERENCE_EVENT|RefEventMutateInput|" + aml);
}
this.setProperty("name", "From input");
var response = this.newItem(this.getType(), this.getAction());
response.setID(this.getID());
response.setProperty("name", "Response only");
return response;

if (Environment.GetEnvironmentVariable("INNOVATOR_HARNESS_REFERENCE_CAPTURE") == "1")
{
    var aml = Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes(this.ToString()));
    Console.WriteLine("HARNESS_REFERENCE_EVENT|RefEventValidateInput|" + aml);
}
if (this.getProperty("name") != "From input")
{
    return this.getInnovator().newError("The separate response replaced shared input");
}
this.setProperty("name", "Validated input");
return this.getInnovator().newResult("Unrelated response");

if (Environment.GetEnvironmentVariable("INNOVATOR_HARNESS_REFERENCE_CAPTURE") == "1")
{
    var aml = Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes(this.ToString()));
    Console.WriteLine("HARNESS_REFERENCE_EVENT|RefEventHydrateInput|" + aml);
}
for (int index = 0; index < this.getItemCount(); index++)
{
    this.getItemByIndex(index).setProperty("name", "Hydrated input");
}
return this.getInnovator().newResult("Another unrelated response");

if (Environment.GetEnvironmentVariable("INNOVATOR_HARNESS_REFERENCE_CAPTURE") == "1")
{
    var aml = Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes(this.ToString()));
    Console.WriteLine("HARNESS_REFERENCE_EVENT|RefEventRejectZero|" + aml);
}
if (this.getProperty("note") == "Reject zero")
{
    var missing = this.newItem("RefEventRecord", "get");
    missing.setProperty("item_number", "MISSING-EVENT");
    return missing.apply();
}
return this.getInnovator().newResult("Accepted");
